Definition re_ivs : list (Z * Z) :=
  [(0x10000,0xb95c0); (0xb95c1,0xb9609); (0xc9609,0xcaf70); (0xeb048,0xeb068); (0xcafa4,0xcaff0); (0xcaff8,0xcb010);
